/**
 * Sanitize a date string in YYYY-MM-DD format.
 * If the date is more than 30 days in the future, try swapping DD↔MM.
 * This catches the common BR↔US date swap (e.g. 2026-06-02 when we're in Feb 2026).
 */
function sanitizeDate(dateStr: string | null | undefined): string | null {
  if (!dateStr) return null;

  // Must be YYYY-MM-DD
  const match = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return dateStr;

  const [, yearStr, monthStr, dayStr] = match;
  const year = parseInt(yearStr);
  const month = parseInt(monthStr);
  const day = parseInt(dayStr);

  const parsed = new Date(year, month - 1, day);
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const diffMs = parsed.getTime() - today.getTime();
  const diffDays = diffMs / (1000 * 60 * 60 * 24);

  // Se a data está mais de 30 dias no futuro, tenta inverter dia↔mês
  // (uma NF nunca seria cadastrada com mais de 30 dias de antecedência)
  if (diffDays > 30 && day <= 12) {
    const swapped = new Date(year, day - 1, month);
    const swappedDiff = (swapped.getTime() - today.getTime()) / (1000 * 60 * 60 * 24);

    // Usa a data invertida se for mais razoável (até 30 dias no futuro ou no passado)
    if (swappedDiff <= 30) {
      const swappedStr = `${yearStr}-${dayStr}-${monthStr}`;
      wideWarn('notas-fiscais.sanitizeDate.auto_correcao', `Data invertida corrigida: ${dateStr} para ${swappedStr}`, { domain: 'notas-fiscais', attributes: { dataOriginal: dateStr, dataCorrigida: swappedStr } });
      return swappedStr;
    }
  }

  return dateStr;
}

/**
 * Detecta se os dados extraídos correspondem a uma NOTA DE TRANSFERÊNCIA
 * (ex: Momma Doces Saudáveis com itens em cx.) que NUNCA deve ser salva
 * como nota fiscal regular nem enviada ao financeiro.
 */
function isTransferNote(data: any): boolean {
  if (!data) return false;
  const fornecedor = (data.fornecedor || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
  return (
    fornecedor.includes('momma doces') ||
    fornecedor.includes('doces saudaveis')
  );
}

const NotasFiscais = () => {
  // MIA 2.0 Glass-Box — declara contexto de linguagem natural pra MIA entender melhor
  useMiaPageContext({
    description: 'Gestão de notas fiscais de compra (OCR + manual) e cadastro de fornecedores.',
    natural_language_hints: [
      '"vencidas" = status pendente_pagamento + data_vencimento < hoje',
      '"a pagar essa semana" = data_vencimento dentro da semana corrente',
      '"transferências" = Notas de Transferência (Momma↔Momma), separadas das NFs de compra',
      '"fornecedores" = painel de cadastro derivado das NFs (CNPJ como PK)',
      '"analytics" = dashboard de evolução de gastos por fornecedor/período',
    ].join('\n'),
    capabilities: ['consultar', 'criar manual', 'upload OCR', 'editar', 'cancelar', 'exportar relatório'],
    destructive_actions: ['cancelar-nf'],
    primary_entity: 'nota_fiscal',
  });

  const [searchTerm, setSearchTerm] = useState("");
  const [isUploadOpen, setIsUploadOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notas, setNotas] = useState([]);
  // Default to current month filter
  const today = new Date();
  const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);
  // Fix: Use local date parts to avoid UTC shift
  const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;

  const prevMonthStart = new Date(today.getFullYear(), today.getMonth() - 1, 1);
  const prevMonthEnd = new Date(today.getFullYear(), today.getMonth(), 0);

  type DateFilterType = 'data_recebimento' | 'created_at' | 'data_nota' | 'data_vencimento';
  const [dateFilterType, setDateFilterType] = useState<DateFilterType>('data_recebimento');
  const [dateFilterRange, setDateFilterRange] = useState<DateRange | undefined>({
    from: startOfMonth,
    to: today,
  });

  const dfStart = dateFilterRange?.from ? format(dateFilterRange.from, 'yyyy-MM-dd') : '';
  const dfEnd = dateFilterRange?.to ? format(dateFilterRange.to, 'yyyy-MM-dd') : '';

  const [statusFilter, setStatusFilter] = useState<'all' | 'processando' | 'processada' | 'erro'>('all');
  const [sortAsc, setSortAsc] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [extractedData, setExtractedData] = useState(null);
  const [editingData, setEditingData] = useState(null);
  const [isViewingPdf, setIsViewingPdf] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [pdfPagesBase64, setPdfPagesBase64] = useState<string[]>([]);
  const [isManualMode, setIsManualMode] = useState(false);

  // Modal states
  const [selectedNota, setSelectedNota] = useState(null);
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isReportsModalOpen, setIsReportsModalOpen] = useState(false);
  const [deletingId, setDeletingId] = useState(null);
  const [isPhotoModalOpen, setIsPhotoModalOpen] = useState(false);
  const [selectedPhoto, setSelectedPhoto] = useState<string | null>(null);
  const [imageLoading, setImageLoading] = useState(false);
  const [imageError, setImageError] = useState(false);
  const [isAnalyticsView, setIsAnalyticsView] = useState(false);
  const [isTransferView, setIsTransferView] = useState(false);
  const [activeTab, setActiveTab] = useState<"notas" | "fornecedores">("notas");
  const [paymentStatusByNotaId, setPaymentStatusByNotaId] = useState<Record<number, { status: string | null; data_pagamento: string | null }>>({});
  const { selectedStore, stores } = useStore();
  const { canSelectStoreNF, canViewNotasFiscais, loading: permsLoading } = usePermissions();
  const [ocrLojaSelecionadaId, setOcrLojaSelecionadaId] = useState<number | null>(null);

  // R1: Seletor de loja local à página de Compras — persiste em localStorage
  const [comprasLojaId, setComprasLojaId] = useState<number | 'all'>(() => {
    // FIX 2: guarda para WebView iOS/Safari privado onde localStorage é bloqueado
    try {
      const stored = localStorage.getItem('compras:lojaId');
      if (!stored || stored === 'all') return 'all';
      const parsed = parseInt(stored, 10);
      return Number.isNaN(parsed) ? 'all' : parsed;
    } catch {
      return 'all';
    }
  });

  useEffect(() => {
    // FIX 2: escrita também guardada
    try {
      localStorage.setItem('compras:lojaId', comprasLojaId.toString());
    } catch {
      // no-op: WebView privado sem acesso a localStorage
    }
  }, [comprasLojaId]);

  // FIX 3: se o id salvo não existe mais em stores (usuário perdeu acesso),
  // resetar para 'all' para não filtrar por loja obsoleta.
  useEffect(() => {
    if (stores.length > 0 && comprasLojaId !== 'all' && !stores.some((s) => s.id === comprasLojaId)) {
      setComprasLojaId('all');
    }
  }, [stores, comprasLojaId]);

  const [ocrFormaPagamento, setOcrFormaPagamento] = useState<string>('boleto');
  const [ocrCreditCardId, setOcrCreditCardId] = useState<number | null>(null);
  const [availableCreditCards, setAvailableCreditCards] = useState<{ id: number; nome: string; bandeira: string; ultimos_digitos?: string }[]>([]);

  // Integração MIA — registrar ações de notas fiscais
  useMiaNotasFiscaisActions({
    setSearchTerm,
    setStatusFilter,
    setDateFilterStart: (v: string) => {
      setDateFilterRange(prev => ({
        from: v ? new Date(v + 'T12:00:00') : undefined,
        to: prev?.to,
      }));
    },
    setDateFilterEnd: (v: string) => {
      setDateFilterRange(prev => ({
        from: prev?.from,
        to: v ? new Date(v + 'T12:00:00') : undefined,
      }));
    },
    setDateFilterType,
    setSortAsc,
    setIsAnalyticsView,
    setIsUploadOpen,
    setSelectedNota,
    setIsDetailsModalOpen,
    setIsEditModalOpen,
    setIsReportsModalOpen,
    notas,
  });

  // Telemetria de busca
  const { trackSearch } = useSearchTelemetry('notas-fiscais');
  const telemetryAttrs = useTelemetryAttrs();
  useEffect(() => {
    trackSearch(searchTerm, notas.length);
  }, [searchTerm, notas.length, trackSearch]);

  // Resumo: total de notas e soma dos valores
  const totalNotas = notas.length;
  const totalValorNotas = notas.reduce((sum, n: any) => sum + parseFloat(String(n?.valor_total || 0)), 0);

  // Formatar data em dd-MM-yyyy
  const formatDateBRDash = (value: any) => {
    if (!value) return '—';
    // YYYY-MM-DD vem do Postgres como string; força meio-dia local pra evitar shift de UTC
    const iso = typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value)
      ? `${value}T12:00:00`
      : value;
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return '—';
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = d.getFullYear();
    return `${day}-${month}-${year}`;
  };

  useEffect(() => {
    loadNotas();
  }, []);

  // Recupera captura pendente se a PWA recarregou após o Android matar o
  // WebView durante a câmera. A captura é persistida pelo DragDropUploadArea
  // em localStorage (sobrevive ao process death — sessionStorage não sobrevive).
  // Tem TTL embutido, então só recupera se foi feita há pouco.
  useEffect(() => {
    const pending = loadPendingCapture();
    if (pending) {
      setSelectedFile(pending.file);
      setSelectedFiles([pending.file]);
      setIsUploadOpen(true);
      toast.success('Foto recuperada — toque em Processar para continuar.');
      // Consome a captura: a foto agora vive no state da página; não queremos
      // que um próximo reload restaure de novo.
      clearPendingCapture();
    }
  }, []);

  // Fetch all active credit cards (qualquer cartão pode ser usado em qualquer loja)
  useEffect(() => {
    const fetchCreditCards = async () => {
      const { data } = await supabase
        .from('credit_cards')
        .select('id, nome, bandeira, ultimos_digitos, loja_id')
        .eq('ativo', true)
        .order('nome');
      setAvailableCreditCards((data || []) as any[]);
    };
    fetchCreditCards();
  }, []);

  // R1/R3: Filtro efetivo de loja — quem tem canSelectStoreNF usa a escolha local;
  // demais usuários continuam usando o contexto global (comportamento preservado — R5).
  const effectiveLojaFilter: number | 'all' = canSelectStoreNF()
    ? comprasLojaId
    : (selectedStore?.id ?? 'all');

  const loadNotas = async () => {
    const startTime = performance.now();
    try {
      const resultCount = await withTrace('financeiro.nf.lista.carregar', async () => {
        let query = supabase
          .from('notas_fiscais')
          .select('*, itens_nota_fiscal(id, nome_produto, categoria, subtotal, quantidade, valor_unitario)')
          // Excluir notas de transferência interna — pertencem à aba Transferências
          .not('fornecedor', 'ilike', '%momma doces%');

        if (searchTerm) {
          // Busca combinada por fornecedor ou número da nota
          query = query.or(`fornecedor.ilike.%${searchTerm}%,numero_nota.ilike.%${searchTerm}%`);
        }
        // R3: filtra pela loja efetiva (local ou global, nunca hardcoded)
        if (effectiveLojaFilter !== 'all') {
          query = query.eq('loja_id', effectiveLojaFilter);
        }
        if (dfStart) {
          query = query.gte(dateFilterType, dateFilterType === 'created_at' ? dfStart : dfStart);
        }
        if (dfEnd) {
          if (dateFilterType === 'created_at') {
            query = query.lte('created_at', dfEnd + 'T23:59:59');
          } else {
            query = query.lte(dateFilterType, dfEnd);
          }
        }
        if (statusFilter !== 'all') {
          query = query.eq('status', statusFilter);
        }

        // Ordenação por data de lançamento no sistema (created_at) — mais recentes acima
        query = query.order('created_at', { ascending: sortAsc });

        const { data, error } = await query;
        if (error) throw error;
        const results = (data || []) as any[];
        setNotas(results);

        // Carrega status financeiro das NFs carregadas
        const ids = results.map((n) => n.id).filter((id): id is number => typeof id === 'number');
        if (ids.length > 0) {
          const { data: pagData } = await supabase
            .from('contas_pagar_receber')
            .select('nota_fiscal_id, status, data_pagamento')
            .in('nota_fiscal_id', ids);
          const map: Record<number, { status: string | null; data_pagamento: string | null }> = {};
          (pagData || []).forEach((p: any) => {
            if (p.nota_fiscal_id != null) {
              map[p.nota_fiscal_id] = { status: p.status, data_pagamento: p.data_pagamento };
            }
          });
          setPaymentStatusByNotaId(map);
        } else {
          setPaymentStatusByNotaId({});
        }
        return results.length;
      }, telemetryAttrs);

      const durationMs = Math.round(performance.now() - startTime);
      wideInfo('financeiro.nf.lista_carregada', 'Lista de notas fiscais carregada com sucesso', enrichWideEvent('notas-fiscais', {
        result_count: resultCount,
        duration_ms: durationMs,
        'nota.periodo': `${dfStart}_${dfEnd}`,
        'nota.filtro_tipo': dateFilterType,
        'nota.filtro': statusFilter,
        'nota.unidade': effectiveLojaFilter !== 'all' ? (stores.find(s => s.id === effectiveLojaFilter)?.name ?? String(effectiveLojaFilter)) : 'todas',
      }));
      recordOperationDuration('financeiro.nf.lista', durationMs);
    } catch (error) {
      const durationMs = Math.round(performance.now() - startTime);
      wideError('financeiro.nf.lista_erro', 'Erro ao carregar lista de notas fiscais', enrichWideEvent('notas-fiscais', {
        'error.message': error instanceof Error ? error.message : String(error),
        duration_ms: durationMs,
        'nota.periodo': `${dfStart}_${dfEnd}`,
        'nota.filtro_tipo': dateFilterType,
        'nota.filtro': statusFilter,
        'nota.unidade': effectiveLojaFilter !== 'all' ? (stores.find(s => s.id === effectiveLojaFilter)?.name ?? String(effectiveLojaFilter)) : 'todas',
      }));
      recordError('financeiro_nf_lista', 'carregar');
      handleError(error, { domain: 'notas-fiscais', operation: 'carregarNotas', showToast: false });
      toast.error('Erro ao carregar notas fiscais');
    }
  };

  const handleFileSelect = (file: File | null) => {
    setSelectedFile(file);
    setSelectedFiles(file ? [file] : []);
    if (!file) {
      setExtractedData(null);
      setEditingData(null);
    }
  };

  const handleFilesSelect = (files: File[]) => {
    setSelectedFiles(files);
    setSelectedFile(files[0] || null);
  };

  const handleManualSave = async (data: any) => {
    setEditingData(data);
    await saveNota();
  };

  // Separar salvamento manual para garantir que o state editingData esteja atualizado
  // Mas como a modal passa o data no onSave, podemos usar esse data diretamente ou setar o state e depois salvar.
  // Vou ajustar o saveNota para aceitar um argumento opcional de dados, ou usar o editingData que já setamos.

  // Refazendo saveNota para ser mais robusto e aceitar dados diretamente se passado
  // ou usar editingData se nao passado.
  const saveNota = async (dataToSave = editingData, options?: { lojaIdOverride?: number | null; formaPagamento?: string; creditCardId?: number | null }) => {
    if (isSaving) return;
    if (!dataToSave) return;

    // GUARD: Notas de transferência NUNCA podem ser salvas como nota fiscal
    if (isTransferNote(dataToSave)) {
      toast.error('Esta nota é de transferência interna (Momma Doces). Use a aba "Notas de Transferência" para lançá-la.');
      return;
    }

    // Atualiza state para garantir consistencia se precisarmos
    setEditingData(dataToSave);

    setIsSaving(true);
    const startTime = performance.now();
    try {
      // Verificação rápida de duplicidade
      if (dataToSave?.numero_nota && dataToSave?.fornecedor) {
        // Se estamos editando uma nota EXISTENTE (tem ID), ignoramos ela mesma na busca de duplicidade?
        // O código original não tratava edição vs criação explicitamente no saveNota para duplicidade, 
        // mas o 'handleEditNota' apenas preenchia o editingData.
        // Se 'selectedNota' existe, é uma edição.

        // TODO: Melhorar lógica de edição vs criação. Por enquanto mantendo compatível com original.
        if (!selectedNota) { // Apenas checa duplicidade se for criação nova
          const { data: existing, error: existingError } = await supabase
            .from('notas_fiscais')
            .select('id')
            .eq('numero_nota', dataToSave.numero_nota)
            .eq('fornecedor', dataToSave.fornecedor)
            .limit(1);
          if (existingError) throw existingError;
          if (existing && existing.length > 0) {
            toast.error('Esta nota já está cadastrada (mesmo fornecedor e número).');
            setIsSaving(false);
            return;
          }
        }
      }

      const { data: userRes } = await supabase.auth.getUser();
      const userId = userRes?.user?.id;
      let fotoUrl: string | null = selectedNota?.imagem_url || null;
      let fotoUrl2: string | null = selectedNota?.imagem_url_2 || null;

      // Upload de todas as fotos/arquivos
      const filesToUpload = selectedFiles.length > 0 ? selectedFiles : selectedFile ? [selectedFile] : [];
      if (filesToUpload.length > 0 && userId) {
        const now = Date.now();
        const baseName = `${userId}_${now}`;
        const uploadedUrls: (string | null)[] = [];

        for (let i = 0; i < Math.min(filesToUpload.length, 2); i++) {
          const file = filesToUpload[i];

          // Foto já subida pro bucket no processImage (OCR) -> reaproveita a URL,
          // sem upload duplicado (evita 2x banda/storage do mesmo arquivo).
          const cachedUrl = ocrUrlByFileRef.current.get(file);
          if (cachedUrl) {
            uploadedUrls.push(cachedUrl);
            continue;
          }

          if (file.type === 'application/pdf') {
            const pages = i === 0 && pdfPagesBase64.length > 0 ? pdfPagesBase64 : await pdfToImageBase64Pages(file);
            const toFile = (b64: string, name: string) => {
              const binStr = atob(b64);
              const len = binStr.length;
              const arr = new Uint8Array(len);
              for (let j = 0; j < len; j++) arr[j] = binStr.charCodeAt(j);
              return new File([arr], name, { type: 'image/jpeg' });
            };
            // Upload primeira página como representação
            if (pages.length > 0) {
              const fname = `${baseName}_f${i + 1}_p1.jpg`;
              const pageFile = toFile(pages[0], fname);
              const { error: upErr } = await supabase.storage.from('notas-fiscais').upload(fname, pageFile);
              if (!upErr) {
                const { data: pub } = supabase.storage.from('notas-fiscais').getPublicUrl(fname);
                uploadedUrls.push(pub?.publicUrl || null);
              } else {
                uploadedUrls.push(null);
              }
            }
          } else {
            const fileExt = file.name.split('.').pop()?.toLowerCase() || 'jpg';
            const fileName = `${baseName}_f${i + 1}.${fileExt}`;
            const { error: uploadError } = await supabase.storage
              .from('notas-fiscais')
              .upload(fileName, file);
            if (!uploadError) {
              const { data: publicData } = supabase.storage
                .from('notas-fiscais')
                .getPublicUrl(fileName);
              uploadedUrls.push(publicData?.publicUrl || null);
            } else {
              uploadedUrls.push(null);
            }
          }
        }

        fotoUrl = uploadedUrls[0] ?? fotoUrl;
        fotoUrl2 = uploadedUrls[1] ?? fotoUrl2;
      }

      // Insert or Update
      // Se tiver selectedNota?.id, é update.
      let notaId = selectedNota?.id;

      dataToSave.data_nota = dataToSave.data_nota || null;
      dataToSave.data_vencimento = dataToSave.data_vencimento || null;
      dataToSave.data_recebimento = dataToSave.data_recebimento || null;

      if (notaId) {
        // Update — não bloqueia edição mesmo sem loja local resolvida (nota já tem loja_id)
        // FIX 4: resolver loja sem clobberar o vínculo existente quando filtro é "Todas as lojas"
        let lojaId: number | undefined | null = options?.lojaIdOverride ?? (canSelectStoreNF() ? (comprasLojaId !== 'all' ? comprasLojaId : undefined) : selectedStore?.id);
        if (lojaId == null) {
          // Sem loja determinada no contexto local — preservar a loja já gravada na nota
          const { data: existingNota } = await supabase
            .from('notas_fiscais')
            .select('loja_id')
            .eq('id', notaId)
            .maybeSingle();
          lojaId = existingNota?.loja_id ?? null;
        }
        const { error: updateError } = await supabase
          .from('notas_fiscais')
          .update({
            numero_nota: dataToSave.numero_nota,
            fornecedor: dataToSave.fornecedor,
            cnpj_emitente: dataToSave.cnpj_emitente || null,
            endereco_emitente: dataToSave.endereco_emitente || null,
            data_nota: dataToSave.data_nota,
            data_vencimento: dataToSave.data_vencimento || null,
            data_recebimento: dataToSave.data_recebimento || null,
            valor_total: dataToSave.valor_total,
            imagem_url: fotoUrl,
            imagem_url_2: fotoUrl2,
            loja_id: lojaId,
            forma_pagamento: options?.formaPagamento || null,
            credit_card_id: options?.formaPagamento === 'cartao_credito' && options?.creditCardId ? options.creditCardId : null,
          })
          .eq('id', notaId);

        if (updateError) throw updateError;

        // Para itens, deletamos e recriamos ou atualizamos?
        // Abordagem simples: deletar todos antigos e inserir novos.
        const { error: delError } = await supabase.from('itens_nota_fiscal').delete().eq('nota_id', notaId);
        if (delError) throw delError;

        // Auto-sync update: route to card or contas_pagar
        try {
          if (dataToSave.valor_total) {
            const isCartao = options?.formaPagamento === 'cartao_credito' && options?.creditCardId;

            if (isCartao) {
              // Remove contas_pagar (may exist if switching from boleto to card)
              await supabase.from('contas_pagar_receber').delete().eq('nota_fiscal_id', notaId);
              // Delete old card transaction and re-create with correct loja
              await supabase.from('credit_card_transactions').delete().eq('nota_fiscal_id', notaId);

              const cardId = options.creditCardId!;
              const purchaseDate = new Date(dataToSave.data_nota || new Date());
              const { data: cardData } = await supabase.from('credit_cards').select('dia_fechamento, dia_vencimento').eq('id', cardId).single();
              const fechamento = cardData?.dia_fechamento || 25;
              const invoiceMonth = new Date(purchaseDate);
              if (purchaseDate.getDate() > fechamento) invoiceMonth.setMonth(invoiceMonth.getMonth() + 1);
              invoiceMonth.setDate(1);
              const mesRef = `${invoiceMonth.getFullYear()}-${String(invoiceMonth.getMonth() + 1).padStart(2, '0')}-01`;

              let invoiceId: number | null = null;
              const { data: existingInv } = await supabase
                .from('credit_card_invoices')
                .select('id')
                .eq('credit_card_id', cardId)
                .eq('mes_referencia', mesRef)
                .maybeSingle();

              if (existingInv) {
                invoiceId = existingInv.id;
              } else {
                const vencDate = new Date(invoiceMonth);
                vencDate.setMonth(vencDate.getMonth() + 1);
                vencDate.setDate(cardData?.dia_vencimento || 10);
                const vencStr = `${vencDate.getFullYear()}-${String(vencDate.getMonth() + 1).padStart(2, '0')}-${String(vencDate.getDate()).padStart(2, '0')}`;
                const { data: newInv } = await supabase
                  .from('credit_card_invoices')
                  .insert({ credit_card_id: cardId, mes_referencia: mesRef, status: 'aberta', data_vencimento: vencStr })
                  .select('id')
                  .single();
                invoiceId = newInv?.id || null;
              }

              await supabase.from('credit_card_transactions').insert({
                credit_card_id: cardId,
                invoice_id: invoiceId,
                loja_id: lojaId ?? null,
                nota_fiscal_id: notaId,
                data: dataToSave.data_nota || new Date().toISOString().split('T')[0],
                descricao: `NF ${dataToSave.numero_nota || 'S/N'} - ${dataToSave.fornecedor}`,
                valor: dataToSave.valor_total,
                categoria: 'Fornecedores',
                parcela_atual: 1,
                total_parcelas: 1,
                origem: 'api',
              });
            } else {
              // Switching away from card? Clean up card transaction
              await supabase.from('credit_card_transactions').delete().eq('nota_fiscal_id', notaId);
              // Normal: update contas_pagar_receber
              await supabase
                .from('contas_pagar_receber')
                .update({
                  descricao: `NF ${dataToSave.numero_nota || 'S/N'} - ${dataToSave.fornecedor}`,
                  valor: dataToSave.valor_total,
                  data_vencimento: dataToSave.data_vencimento || null,
                  data_competencia: dataToSave.data_nota || null,
                  loja_id: lojaId || null,
                  url_comprovante: fotoUrl,
                  forma_pagamento: options?.formaPagamento || null,
                })
                .eq('nota_fiscal_id', notaId);
            }
          }
        } catch (syncUpErr) {
          handleError(syncUpErr, { domain: 'notas-fiscais', operation: 'atualizarSincronizacaoFinanceiro', showToast: false });
        }

      } else {
        // Insert — R4: nunca gravar loja_id nulo silenciosamente em nota nova
        const lojaId = options?.lojaIdOverride ?? (canSelectStoreNF() ? (comprasLojaId !== 'all' ? comprasLojaId : undefined) : selectedStore?.id);
        if (!lojaId) {
          toast.error('Selecione uma loja específica para lançar a nota.');
          setIsSaving(false);
          return;
        }
        const { data: nota, error: notaError } = await supabase
          .from('notas_fiscais')
          .insert({
            numero_nota: dataToSave.numero_nota,
            fornecedor: dataToSave.fornecedor,
            cnpj_emitente: dataToSave.cnpj_emitente || null,
            endereco_emitente: dataToSave.endereco_emitente || null,
            data_nota: dataToSave.data_nota,
            data_vencimento: dataToSave.data_vencimento || null,
            data_recebimento: dataToSave.data_recebimento || null,
            valor_total: dataToSave.valor_total,
            status: 'processada',
            user_id: userId,
            imagem_url: fotoUrl,
            imagem_url_2: fotoUrl2,
            loja_id: lojaId,
            forma_pagamento: options?.formaPagamento || null,
            credit_card_id: options?.formaPagamento === 'cartao_credito' && options?.creditCardId ? options.creditCardId : null,
          })
          .select()
          .single();

        if (notaError) throw notaError;
        notaId = nota.id;

        // Auto-sync: Route to credit card or contas a pagar
        try {
          if (dataToSave.valor_total) {
            const isCartao = options?.formaPagamento === 'cartao_credito' && options?.creditCardId;

            if (isCartao) {
              // Route to credit card transactions instead of contas_pagar_receber
              const cardId = options.creditCardId!;
              // Get or create the invoice for the month
              const purchaseDate = new Date(dataToSave.data_nota || new Date());
              // Fetch card to check dia_fechamento
              const { data: cardData } = await supabase.from('credit_cards').select('dia_fechamento, dia_vencimento').eq('id', cardId).maybeSingle();
              const fechamento = cardData?.dia_fechamento || 25;
              const invoiceMonth = new Date(purchaseDate);
              if (purchaseDate.getDate() > fechamento) invoiceMonth.setMonth(invoiceMonth.getMonth() + 1);
              invoiceMonth.setDate(1);
              const mesRef = `${invoiceMonth.getFullYear()}-${String(invoiceMonth.getMonth() + 1).padStart(2, '0')}-01`;

              // Upsert invoice
              let invoiceId: number | null = null;
              const { data: existingInv } = await supabase
                .from('credit_card_invoices')
                .select('id')
                .eq('credit_card_id', cardId)
                .eq('mes_referencia', mesRef)
                .maybeSingle();

              if (existingInv) {
                invoiceId = existingInv.id;
              } else {
                const vencDate = new Date(invoiceMonth);
                vencDate.setMonth(vencDate.getMonth() + 1);
                vencDate.setDate(cardData?.dia_vencimento || 10);
                const vencStr = `${vencDate.getFullYear()}-${String(vencDate.getMonth() + 1).padStart(2, '0')}-${String(vencDate.getDate()).padStart(2, '0')}`;
                const { data: newInv } = await supabase
                  .from('credit_card_invoices')
                  .insert({ credit_card_id: cardId, mes_referencia: mesRef, status: 'aberta', data_vencimento: vencStr })
                  .select('id')
                  .single();
                invoiceId = newInv?.id || null;
              }

              await supabase.from('credit_card_transactions').insert({
                credit_card_id: cardId,
                invoice_id: invoiceId,
                loja_id: lojaId ?? null,
                nota_fiscal_id: notaId,
                data: dataToSave.data_nota || new Date().toISOString().split('T')[0],
                descricao: `NF ${dataToSave.numero_nota || 'S/N'} - ${dataToSave.fornecedor}`,
                valor: dataToSave.valor_total,
                categoria: 'Fornecedores',
                parcela_atual: 1,
                total_parcelas: 1,
                origem: 'api',
              });
            } else {
              // Normal flow: create conta a pagar
              const txPayload = {
                descricao: `NF ${dataToSave.numero_nota || 'S/N'} - ${dataToSave.fornecedor}`,
                valor: dataToSave.valor_total,
                data_vencimento: dataToSave.data_vencimento || null,
                data_competencia: dataToSave.data_nota || null,
                tipo: 'despesa',
                status: 'pendente',
                origem: 'nota_fiscal',
                categoria: 'fornecedores',
                forma_pagamento: options?.formaPagamento || null,
                loja_id: lojaId || null,
                numero_parcelas: 1,
                nota_fiscal_id: notaId,
                url_comprovante: fotoUrl,
              };
              await supabase.from('contas_pagar_receber').insert(txPayload);
            }
          }
        } catch (syncErr) {
          handleError(syncErr, { domain: 'notas-fiscais', operation: 'sincronizarFinanceiro', showToast: false });
          // Non-blocking error
        }
      }

      // Save items
      if (dataToSave.itens && dataToSave.itens.length > 0) {
        const { error: itensError } = await supabase
          .from('itens_nota_fiscal')
          .insert(
            dataToSave.itens.map((item: any) => ({
              nota_id: notaId,
              nome_produto: item.nome_produto,
              quantidade: item.quantidade,
              valor_unitario: item.valor_unitario,
              subtotal: item.subtotal,
              categoria: normalizeCategoria(item.categoria)
            }))
          );

        if (itensError) throw itensError;
      }

      // Mantém cadastro de fornecedores em dia — upsert por CNPJ (telefone preservado)
      const cnpjDigits = (dataToSave.cnpj_emitente || '').replace(/\D/g, '');
      if (cnpjDigits.length === 14 && dataToSave.fornecedor) {
        try {
          const { data: existing } = await supabase
            .from('fornecedores')
            .select('cnpj')
            .eq('cnpj', cnpjDigits)
            .maybeSingle();
          if (!existing) {
            await supabase.from('fornecedores').insert({
              cnpj: cnpjDigits,
              nome: dataToSave.fornecedor,
              endereco: dataToSave.endereco_emitente || null,
            });
          }
        } catch (forErr) {
          handleError(forErr, { domain: 'notas-fiscais', operation: 'upsertFornecedor', showToast: false });
        }
      }

      toast.success(notaId === selectedNota?.id ? 'Nota atualizada com sucesso!' : 'Nota fiscal salva com sucesso!');
      const durationMs = Math.round(performance.now() - startTime);
      wideInfo('financeiro.nf.processada', 'Nota fiscal processada com sucesso', enrichWideEvent('notas-fiscais', {
        'nota.numero': dataToSave.numero_nota || 'S/N',
        'nota.fornecedor': dataToSave.fornecedor || '',
        'nota.valor': dataToSave.valor_total || 0,
        'nota.operacao': selectedNota?.id ? 'update' : 'insert',
        duration_ms: durationMs,
      }));
      recordOperation('financeiro.nf');
      recordOperationDuration('financeiro.nf', durationMs);
      resetUploadModal();
      loadNotas();
    } catch (error) {
      const durationMs = Math.round(performance.now() - startTime);
      wideError('financeiro.nf.erro', 'Erro ao processar nota fiscal', enrichWideEvent('notas-fiscais', {
        'nota.numero': dataToSave.numero_nota || 'S/N',
        'nota.fornecedor': dataToSave.fornecedor || '',
        'error.message': error instanceof Error ? error.message : String(error),
        duration_ms: durationMs,
      }));
      recordError('financeiro_nf', 'processar');
      handleError(error, { domain: 'notas-fiscais', operation: 'salvarNota', showToast: false });
      toast.error('Erro ao salvar nota fiscal');
    } finally {
      setIsSaving(false);
    }
  };

  // Configurar worker do pdf.js (carregado via CDN para simplicidade)
  GlobalWorkerOptions.workerSrc = workerSrc;

  const pdfToImageBase64Pages = async (file: File): Promise<string[]> => {
    const arrayBuffer = await file.arrayBuffer();
    const worker = new Worker(workerSrc, { type: 'module' });
    const pdf = await getDocument({ data: arrayBuffer, worker }).promise;
    const pagesBase64: string[] = [];

    try {
      for (let i = 1; i <= pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        // scale 2.6 + clamp em NF_IMAGE_MAX_DIM: o canvas é liberado a cada
        // página (logo abaixo), então o pico é de uma página por vez — dá pra
        // renderizar com resolução suficiente pro OCR ler fonte miúda. O 2.0
        // anterior degradava texto pequeno do DANFE.
        const baseScale = 2.6;
        let viewport = page.getViewport({ scale: baseScale });
        const maxDim = NF_IMAGE_MAX_DIM;
        if (viewport.width > maxDim || viewport.height > maxDim) {
          const scaleFactor = Math.min(maxDim / viewport.width, maxDim / viewport.height);
          viewport = page.getViewport({ scale: baseScale * scaleFactor });
        }
        const canvas = document.createElement('canvas');
        const context = canvas.getContext('2d');
        if (!context) continue;
        canvas.width = Math.floor(viewport.width);
        canvas.height = Math.floor(viewport.height);
        await page.render({ canvasContext: context, viewport }).promise;
        const dataUrl = canvas.toDataURL('image/jpeg', NF_IMAGE_JPEG_QUALITY);
        const base64 = dataUrl.split(',')[1];
        pagesBase64.push(base64);
        // Libera o backing store do canvas a cada página: sem isso, todos os
        // canvases ficavam vivos até o fim do loop, multiplicando o pico de RAM.
        canvas.width = 0;
        canvas.height = 0;
      }
    } finally {
      // Garante que o Worker e o documento do pdf.js sejam liberados mesmo em
      // erro — Worker nunca terminado era fonte direta de vazamento de memória.
      pdf.destroy?.();
      worker.terminate();
    }
    return pagesBase64;
  };

  const normalizeItems = (items: any[]): any[] => {
    const map: Record<string, { nome_produto: string; quantidade: number; subtotal: number | null; valor_unitario: number | null; categoria: string | null }> = {};
    for (const it of items || []) {
      const nome = String(it?.nome_produto || '').trim();
      if (!nome) continue;
      const key = nome.toLowerCase();
      const qtd = typeof it?.quantidade === 'string' ? parseFloat(it.quantidade) : (it?.quantidade ?? 0);
      const sub = typeof it?.subtotal === 'string' ? parseFloat(it.subtotal) : (it?.subtotal ?? null);
      const unit = typeof it?.valor_unitario === 'string' ? parseFloat(it.valor_unitario) : (it?.valor_unitario ?? null);
      const cat = (it?.categoria ?? null) as string | null;
      if (!map[key]) {
        map[key] = { nome_produto: nome, quantidade: 0, subtotal: null, valor_unitario: unit, categoria: cat };
      }
      map[key].quantidade += qtd || 0;
      if (sub != null) {
        map[key].subtotal = (map[key].subtotal ?? 0) + sub;
      }
      if (map[key].valor_unitario == null && unit != null) {
        map[key].valor_unitario = unit;
      }
      if (map[key].categoria == null && cat != null) {
        map[key].categoria = cat;
      }
    }
    const result: any[] = [];
    for (const k in map) {
      const v = map[k];
      let unit = v.valor_unitario;
      if ((unit == null || isNaN(unit)) && v.subtotal != null && v.quantidade > 0) {
        unit = Number((v.subtotal / v.quantidade).toFixed(4));
      }
      result.push({ nome_produto: v.nome_produto, quantidade: Number(Number(v.quantidade || 0).toFixed(3)), valor_unitario: unit ?? null, subtotal: v.subtotal != null ? Number(Number(v.subtotal).toFixed(2)) : null, categoria: v.categoria });
    }
    return result;
  };

  // Cache File -> URL pública subida no OCR (processImage), pra o save reaproveitar
  // sem re-upload. Keyed pelo objeto File (robusto a reordenação/remoção de página).
  const ocrUrlByFileRef = useRef<Map<File, string>>(new Map());

  // Sobe a foto pro bucket pro OCR ler por URL. Streaming de bytes (sem decode)
  // => sem pico de memória no cliente. Retorna a URL pública ou null se falhar.
  const uploadOcrPhoto = async (
    file: File,
    uid: string,
    stamp: number,
    idx: number,
  ): Promise<string | null> => {
    try {
      const ext = file.name.split('.').pop()?.toLowerCase() || 'jpg';
      const fname = `${uid}_${stamp}_f${idx + 1}.${ext}`;
      const { error } = await supabase.storage
        .from('notas-fiscais')
        .upload(fname, file, { upsert: true });
      if (error) return null;
      const { data } = supabase.storage.from('notas-fiscais').getPublicUrl(fname);
      return data?.publicUrl || null;
    } catch {
      return null;
    }
  };

  const processImage = async () => {
    const filesToProcess = selectedFiles.length > 0 ? selectedFiles : selectedFile ? [selectedFile] : [];
    if (filesToProcess.length === 0) {
      toast.error('Selecione uma imagem ou PDF primeiro');
      return;
    }

    setIsProcessing(true);
    try {
      // Monta as tarefas de OCR. FOTO: sobe pro bucket e manda só a URL — a edge
      // function baixa e faz o base64 NO SERVIDOR, então o WebView do Android
      // nunca monta o base64 da foto em alta resolução em memória (era o gatilho
      // do OOM) e a IA recebe a imagem na resolução cheia. PDF: segue por base64
      // (páginas renderizadas no cliente, tamanho limitado e liberado por página).
      const { data: userRes } = await supabase.auth.getUser();
      const uid = userRes?.user?.id;
      const stamp = Date.now();

      const ocrTasks: Array<{ imageUrl: string } | { imageBase64: string }> = [];
      // Zera o cache de URLs subidas; o save reaproveita estas (sem re-upload).
      ocrUrlByFileRef.current = new Map();

      for (let idx = 0; idx < filesToProcess.length; idx++) {
        const file = filesToProcess[idx];
        if (file.type === 'application/pdf') {
          const pagesBase64 = await pdfToImageBase64Pages(file);
          setPdfPagesBase64(pagesBase64);
          for (const p of pagesBase64) ocrTasks.push({ imageBase64: p });
        } else {
          const url = uid ? await uploadOcrPhoto(file, uid, stamp, idx) : null;
          if (url) {
            ocrUrlByFileRef.current.set(file, url);
            ocrTasks.push({ imageUrl: url });
          } else {
            // Fallback (upload falhou/offline): base64 lossless do cliente.
            const b64 = await fileToOcrBase64(file);
            ocrTasks.push({ imageBase64: b64 });
          }
        }
      }

      // Processa cada imagem com OCR
      const results: any[] = [];
      for (let i = 0; i < ocrTasks.length; i++) {
        const task = ocrTasks[i];
        const { data, error } = await supabase.functions.invoke('process-invoice-ocr', {
          body: task,
        });
        // Libera a base64 do fallback já enviada (URLs são leves, não precisam).
        if ('imageBase64' in task) (task as { imageBase64: string }).imageBase64 = '';
        if (error) throw new MiaDataError({
          code: MIA_ERROR_CODES.INFRA_EDGE_FUNCTION,
          message: error.message || 'Falha na edge function process-invoice-ocr',
          userMessage: 'Erro ao processar a nota fiscal pelo OCR. Tente novamente.',
          cause: error instanceof Error ? error : undefined,
        });
        // Edge function retorna 200 com { error } quando todos os modelos falham
        if (data?.error) throw new MiaDataError({
          code: MIA_ERROR_CODES.INFRA_EDGE_FUNCTION,
          message: data.error,
          userMessage: data.error,
        });
        results.push(data);
      }

      // Merge dos resultados de todas as páginas/fotos
      const merged: any = {
        numero_nota: null,
        fornecedor: null,
        data_nota: null,
        data_vencimento: null,
        valor_total: null,
        itens: []
      };

      for (const r of results) {
        if (r) {
          if (!merged.numero_nota && r.numero_nota) merged.numero_nota = r.numero_nota;
          if (!merged.fornecedor && r.fornecedor) merged.fornecedor = r.fornecedor;
          if (!merged.data_nota && r.data_nota) merged.data_nota = r.data_nota;
          if (!merged.data_vencimento && r.data_vencimento) merged.data_vencimento = r.data_vencimento;
          if (merged.valor_total == null && r.valor_total != null) merged.valor_total = r.valor_total;
          if (Array.isArray(r.itens)) merged.itens = merged.itens.concat(r.itens);
        }
      }

      const normalized = { ...merged, itens: normalizeItems(merged.itens) };
      setExtractedData(normalized);
      setEditingData(normalized);
      toast.success(ocrTasks.length > 1
        ? `Nota fiscal processada com sucesso! (${ocrTasks.length} páginas lidas)`
        : 'Nota fiscal processada com sucesso!');
    } catch (error) {
      handleError(error, { domain: 'notas-fiscais', operation: 'processamentoNota', showToast: false });
      const msg = error instanceof MiaDataError
        ? error.userMessage
        : 'Não conseguimos ler a nota. Tente uma foto mais nítida ou reenvie.';
      toast.error(msg, {
        description: 'A foto continua carregada — clique em Processar novamente.',
        duration: 6000,
      });
    } finally {
      setIsProcessing(false);
    }
