import { useState, useEffect } from 'react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import { useMia, useMiaGlassBoxContext } from '@/shared/contexts/MiaContext';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { Loader2, Trash2 } from 'lucide-react';
import { toast } from 'sonner';
import { useIsMobile } from '@/shared/hooks/use-mobile';
import { cn } from '@/shared/lib/utils';
import { CATEGORIAS_NF, normalizeCategoria } from '@/features/notas-fiscais/lib/categorias';

interface ManualInvoiceModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: any, options?: { lojaIdOverride?: number | null; formaPagamento?: string; creditCardId?: number | null }) => Promise<void>;
  initialData?: any;
  isSaving: boolean;
  stores?: { id: number; name: string }[];
  selectedStoreId?: number | null;
  creditCards?: { id: number; nome: string; bandeira: string; ultimos_digitos?: string; loja_id?: number }[];
}

export function ManualInvoiceModal({
  isOpen,
  onClose,
  onSave,
  initialData,
  isSaving,
  stores = [],
  selectedStoreId,
  creditCards = [],
}: ManualInvoiceModalProps) {
  const isMobile = useIsMobile();
  // Protege modal de fechar acidentalmente quando MIA está atuando — user
  // clicando no chat MIA não pode disparar onPointerDownOutside do Dialog.
  const { isStreaming } = useMia();
  const { isExecuting } = useMiaGlassBoxContext();
  const miaActive = isStreaming || isExecuting;
  const [data, setData] = useState<any>({
    numero_nota: '',
    fornecedor: '',
    data_nota: '',
    data_vencimento: '',
    data_recebimento: '',
    valor_total: 0,
    itens: [],
  });
  const [lojaId, setLojaId] = useState<number | null>(null);
  const [formaPagamento, setFormaPagamento] = useState<string>('boleto');
  const [creditCardId, setCreditCardId] = useState<number | null>(null);

  useEffect(() => {
    if (isOpen && initialData) {
      setData(initialData);
    } else if (isOpen && !initialData) {
      setData({ numero_nota: '', fornecedor: '', data_nota: '', data_vencimento: '', data_recebimento: '', valor_total: 0, itens: [] });
    }
    if (isOpen) {
      // FIX 5: em edição, priorizar loja da própria nota; fallback para selectedStoreId em nota nova
      setLojaId(initialData?.loja_id ?? selectedStoreId ?? null);
      setFormaPagamento('boleto');
      setCreditCardId(null);
    }
  }, [isOpen, initialData, selectedStoreId]);

  const handleSave = async () => {
    if (!data.fornecedor) {
      toast.error('Preencha o fornecedor.');
      return;
    }
    // R4: quando há seletor de loja visível (stores disponíveis), exige loja escolhida
    if (stores.length > 0 && !lojaId) {
      toast.error('Selecione uma loja para lançar a nota.');
      return;
    }
    await onSave(data, {
      lojaIdOverride: lojaId,
      formaPagamento: formaPagamento || null,
      creditCardId: formaPagamento === 'cartao_credito' ? creditCardId : null,
    });
  };

  const updateItem = (index: number, field: string, value: any) => {
    const newItens = [...(data.itens || [])];
    const currentItem = { ...newItens[index], [field]: value };

    // Auto-calculate subtotal if quantity or unit price changes
    if (field === 'quantidade' || field === 'valor_unitario') {
      const qty =
        field === 'quantidade'
          ? parseFloat(value)
          : parseFloat(currentItem.quantidade);
      const price =
        field === 'valor_unitario'
          ? parseFloat(value)
          : parseFloat(currentItem.valor_unitario);

      if (!isNaN(qty) && !isNaN(price)) {
        currentItem.subtotal = parseFloat((qty * price).toFixed(2));
      }
    }

    newItens[index] = currentItem;

    // Optional: Update total invoice value based on items sum
    const newTotal = newItens.reduce(
      (sum: number, item: any) => sum + (parseFloat(item.subtotal) || 0),
      0,
    );

    setData({ ...data, itens: newItens, valor_total: newTotal });
  };

  const addItem = () => {
    setData({
      ...data,
      itens: [
        ...(data.itens || []),
        {
          nome_produto: '',
          quantidade: 0,
          valor_unitario: null,
          subtotal: null,
          categoria: '',
        },
      ],
    });
  };

  const removeItem = (index: number) => {
    const newItens = [...(data.itens || [])];
    newItens.splice(index, 1);

    // Recalculate total when item is removed
    const newTotal = newItens.reduce(
      (sum: number, item: any) => sum + (parseFloat(item.subtotal) || 0),
      0,
    );

    setData({ ...data, itens: newItens, valor_total: newTotal });
  };

  return (
    <Dialog
      open={isOpen}
      onOpenChange={(open) => !open && onClose()}
      // modal={false} quando MIA atua OU aguarda clarification → Radix não
      // bloqueia interação com o resto da UI (chat MIA, clarification form).
      // Sem isso, mesmo após MIA terminar de executar e aguardar resposta,
      // qualquer click no form fechava o modal (Radix considerava "outside").
      modal={!miaActive && !document.documentElement.hasAttribute('data-mia-clarification-pending')}
    >
      <DialogContent
        data-mia-modal="nova-nota-manual"
        data-mia-domain="financeiro"
        // Protege modal: quando MIA está atuando OU aguardando clarification,
        // click fora NÃO fecha. Padrão Radix: e.preventDefault().
        onPointerDownOutside={(e) => {
          if (miaActive || document.documentElement.hasAttribute('data-mia-clarification-pending')) {
            e.preventDefault();
          }
        }}
        onInteractOutside={(e) => {
          if (miaActive || document.documentElement.hasAttribute('data-mia-clarification-pending')) {
            e.preventDefault();
          }
        }}
        onEscapeKeyDown={(e) => {
          if (miaActive || document.documentElement.hasAttribute('data-mia-clarification-pending')) {
            e.preventDefault();
          }
        }}
        className={cn(
          'flex flex-col p-0 gap-0 overflow-hidden',
          isMobile
            ? 'h-[100dvh] w-full max-w-none rounded-none border-0'
            : 'max-w-4xl max-h-[85vh] rounded-xl',
        )}
      >
        {/* Header */}
        <div className="px-6 py-4 border-b border-[#57715B]/10 bg-[#F5F5F0] z-10">
          <DialogHeader>
            <DialogTitle className="text-[#2D362E] text-xl font-serif">
              Nota Manual
            </DialogTitle>
            <DialogDescription className="text-[#57715B]/70">
              Preencha os dados da nota fiscal e os itens recebidos.
            </DialogDescription>
          </DialogHeader>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6 bg-[#F5F5F0]/50">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <Label
                htmlFor="numero_nota"
                className="text-[#57715B] font-semibold mb-1.5 block"
              >
                Número da Nota (Opcional)
              </Label>
              <Input
                id="numero_nota"
                data-mia-field="numero_nota"
                data-mia-type="text"
                className="rounded-xl border-[#57715B]/20 focus:border-[#57715B] focus:ring-[#57715B]/20 bg-white/50"
                value={data.numero_nota || ''}
                onChange={(e) =>
                  setData({ ...data, numero_nota: e.target.value })
                }
                placeholder="Ex: 12345"
              />
            </div>
            <div>
              <Label
                htmlFor="fornecedor"
                className="text-[#57715B] font-semibold mb-1.5 block"
              >
                Fornecedor
              </Label>
              <Input
                id="fornecedor"
                data-mia-field="fornecedor"
                data-mia-type="text"
                data-mia-required="true"
                className="rounded-xl border-[#57715B]/20 focus:border-[#57715B] focus:ring-[#57715B]/20 bg-white/50"
                value={data.fornecedor || ''}
                onChange={(e) =>
                  setData({ ...data, fornecedor: e.target.value })
                }
                placeholder="Ex: Fornecedor XYZ"
              />
            </div>
            <div>
              <Label
                htmlFor="cnpj_emitente"
                className="text-[#57715B] font-semibold mb-1.5 block"
              >
                CNPJ
              </Label>
              <Input
                id="cnpj_emitente"
                data-mia-field="cnpj"
                data-mia-type="text"
                className="rounded-xl border-[#57715B]/20 focus:border-[#57715B] focus:ring-[#57715B]/20 bg-white/50"
                value={data.cnpj_emitente || ''}
                onChange={(e) =>
                  setData({ ...data, cnpj_emitente: e.target.value.replace(/\D/g, '').slice(0, 14) })
                }
                placeholder="14 dígitos (ex: 12345678000199)"
                inputMode="numeric"
              />
            </div>
            <div className="sm:col-span-2">
              <Label
                htmlFor="endereco_emitente"
                className="text-[#57715B] font-semibold mb-1.5 block"
              >
                Endereço do Fornecedor
              </Label>
              <Input
                id="endereco_emitente"
                data-mia-field="endereco_fornecedor"
                data-mia-type="text"
                className="rounded-xl border-[#57715B]/20 focus:border-[#57715B] focus:ring-[#57715B]/20 bg-white/50"
                value={data.endereco_emitente || ''}
                onChange={(e) =>
                  setData({ ...data, endereco_emitente: e.target.value })
                }
                placeholder="Rua, número, bairro, cidade - UF, CEP"
              />
            </div>
            <div>
              <Label
                htmlFor="data_nota"
                className="text-[#57715B] font-semibold mb-1.5 block"
              >
                Data da Nota
              </Label>
              <Input
                id="data_nota"
                type="date"
                data-mia-field="data_nota"
                data-mia-type="date"
                className="rounded-xl border-[#57715B]/20 focus:border-[#57715B] focus:ring-[#57715B]/20 bg-white/50"
                value={data.data_nota || ''}
                onChange={(e) =>
                  setData({ ...data, data_nota: e.target.value })
                }
              />
            </div>
            <div>
              <Label
                htmlFor="data_vencimento"
                className="text-[#57715B] font-semibold mb-1.5 block"
              >
                Vencimento (Boleto)
              </Label>
              <Input
                id="data_vencimento"
                type="date"
                data-mia-field="data_vencimento"
                data-mia-type="date"
                className="rounded-xl border-[#57715B]/20 focus:border-[#57715B] focus:ring-[#57715B]/20 bg-white/50"
                value={data.data_vencimento || ''}
                onChange={(e) =>
                  setData({ ...data, data_vencimento: e.target.value })
                }
              />
            </div>
            <div>
              <Label
                htmlFor="data_recebimento"
                className="text-[#57715B] font-semibold mb-1.5 block"
              >
                Recebimento
              </Label>
              <Input
                id="data_recebimento"
                type="date"
                data-mia-field="data_recebimento"
                data-mia-type="date"
                className="rounded-xl border-[#57715B]/20 focus:border-[#57715B] focus:ring-[#57715B]/20 bg-white/50"
                value={data.data_recebimento || ''}
                onChange={(e) =>
                  setData({ ...data, data_recebimento: e.target.value })
                }
              />
            </div>
            <div>
              <Label
                htmlFor="valor_total"
                className="text-[#57715B] font-semibold mb-1.5 block"
              >
                Valor Total
              </Label>
              <Input
                id="valor_total"
                type="number"
                step="0.01"
                data-mia-field="valor_total"
                data-mia-type="number"
                data-mia-required="true"
                className="rounded-xl border-[#57715B]/20 focus:border-[#57715B] focus:ring-[#57715B]/20 bg-white/50"
                value={data.valor_total || ''}
                onChange={(e) =>
                  setData({ ...data, valor_total: parseFloat(e.target.value) })
                }
              />
            </div>
            <div>
              <Label className="text-[#57715B] font-semibold mb-1.5 block">Forma de Pagamento</Label>
              <Select value={formaPagamento} onValueChange={(v) => { setFormaPagamento(v); if (v !== 'cartao_credito') setCreditCardId(null); }}>
                <SelectTrigger
                  data-mia-filter="forma_pagamento"
                  data-mia-options="boleto,cartao_credito,pix,dinheiro,transferencia"
                  className="rounded-xl border-[#57715B]/20 focus:border-[#57715B] bg-white/80"
                >
                  <SelectValue placeholder="Selecionar" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="boleto" data-mia-option-value="boleto" data-mia-option-label="Boleto">Boleto</SelectItem>
                  <SelectItem value="cartao_credito" data-mia-option-value="cartao_credito" data-mia-option-label="Cartão de Crédito">Cartão de Crédito</SelectItem>
                  <SelectItem value="pix" data-mia-option-value="pix" data-mia-option-label="PIX">PIX</SelectItem>
                  <SelectItem value="dinheiro" data-mia-option-value="dinheiro" data-mia-option-label="Dinheiro">Dinheiro</SelectItem>
                  <SelectItem value="transferencia" data-mia-option-value="transferencia" data-mia-option-label="Transferência">Transferência</SelectItem>
                </SelectContent>
              </Select>
            </div>
            {formaPagamento === 'cartao_credito' && creditCards.length > 0 && (
              <div>
                <Label className="text-[#57715B] font-semibold mb-1.5 block">Cartão de Crédito</Label>
                <Select value={creditCardId?.toString() || ''} onValueChange={(v) => setCreditCardId(parseInt(v))}>
                  <SelectTrigger className="rounded-xl border-violet-300 focus:border-violet-500 bg-violet-50/50">
                    <SelectValue placeholder="Selecionar cartão" />
                  </SelectTrigger>
                  <SelectContent>
                    {creditCards.map(cc => (
                      <SelectItem key={cc.id} value={cc.id.toString()}>
                        {cc.nome} {cc.ultimos_digitos ? `(****${cc.ultimos_digitos})` : ''} - {cc.bandeira}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            {stores.length > 0 && (
              <div>
                <Label className="text-[#57715B] font-semibold mb-1.5 block">Loja</Label>
                <Select value={lojaId?.toString() || ''} onValueChange={(v) => setLojaId(parseInt(v))}>
                  <SelectTrigger
                    data-mia-filter="loja_nf"
                    data-mia-options={stores.map((s) => s.name).join(',')}
                    className="rounded-xl border-[#57715B]/20 focus:border-[#57715B] bg-white/80"
                  >
                    <SelectValue placeholder="Selecionar loja" />
                  </SelectTrigger>
                  <SelectContent>
                    {stores.map(store => (
                      <SelectItem
                        key={store.id}
                        value={store.id.toString()}
                        data-mia-option-value={store.name}
                        data-mia-option-label={store.name}
                      >
                        {store.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
          </div>

          <div>
            <div className="flex items-center justify-between mb-4">
              <Label className="text-lg font-serif text-[#2D362E]">
                Itens da Nota Fiscal
              </Label>
              <Button
                data-mia-action="adicionar-item-nf"
                data-mia-description="Adiciona uma linha de item à nota fiscal (sub-form com nome_produto, quantidade, valor_unitario, categoria)"
                aria-label="adicionar-item-nf"
                variant="outline"
                size="sm"
                onClick={addItem}
                className="rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 hover:text-[#57715B]"
              >
                Adicionar Item
              </Button>
            </div>

            <div className="space-y-4" data-mia-subform="itens-nota" data-mia-subform-add="adicionar-item-nf">
              {data.itens?.map((item: any, index: number) => (
                <div
                  key={index}
                  data-mia-subform-row="itens-nota"
                  data-mia-row-index={index}
                  className="flex flex-col gap-3 p-4 border border-[#57715B]/10 rounded-2xl bg-white/60 shadow-sm transition-all hover:shadow-md hover:border-[#57715B]/20"
                >
                  {/* Header do item mobile */}
                  <div className="flex justify-between items-center sm:hidden">
                    <span className="text-sm font-bold text-[#57715B]">
                      Item {index + 1}
                    </span>
                    <Button
                      variant="ghost"
                      size="icon"
                      data-mia-action="remover-item-nf"
                      data-mia-row-index={index}
                      className="h-6 w-6 text-red-500 hover:text-red-600 hover:bg-red-50 rounded-full"
                      onClick={() => removeItem(index)}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-12 gap-3 items-end">
                    <div className="sm:col-span-4">
                      <Label className="text-xs font-semibold text-[#57715B] mb-1.5 block">
                        Produto
                      </Label>
                      <Input
                        placeholder="Nome do produto"
                        data-mia-field={`itens[${index}].nome_produto`}
                        className="rounded-lg border-[#57715B]/10 focus:border-[#57715B] h-9 text-sm"
                        value={item.nome_produto || ''}
                        onChange={(e) =>
                          updateItem(index, 'nome_produto', e.target.value)
                        }
                      />
                    </div>
                    <div className="sm:col-span-2">
                      <Label className="text-xs font-semibold text-[#57715B] mb-1.5 block">
                        Qtd
                      </Label>
                      <Input
                        type="number"
                        placeholder="0"
                        data-mia-field={`itens[${index}].quantidade`}
                        className="rounded-lg border-[#57715B]/10 focus:border-[#57715B] h-9 text-sm"
                        value={item.quantidade || ''}
                        onChange={(e) =>
                          updateItem(
                            index,
                            'quantidade',
                            parseFloat(e.target.value),
                          )
                        }
                      />
                    </div>
                    <div className="sm:col-span-2">
                      <Label className="text-xs font-semibold text-[#57715B] mb-1.5 block">
                        R$ Unit.
                      </Label>
                      <Input
                        type="number"
                        step="0.01"
                        placeholder="0.00"
                        data-mia-field={`itens[${index}].valor_unitario`}
                        className="rounded-lg border-[#57715B]/10 focus:border-[#57715B] h-9 text-sm"
                        value={item.valor_unitario || ''}
                        onChange={(e) =>
                          updateItem(
                            index,
                            'valor_unitario',
                            parseFloat(e.target.value),
                          )
                        }
                      />
                    </div>
                    <div className="sm:col-span-2">
                      <Label className="text-xs font-semibold text-[#57715B] mb-1.5 block">
                        R$ Total
                      </Label>
                      <Input
                        type="number"
                        step="0.01"
                        placeholder="0.00"
                        data-mia-field={`itens[${index}].subtotal`}
                        className="rounded-lg border-[#57715B]/10 focus:border-[#57715B] h-9 text-sm"
                        value={item.subtotal || ''}
                        onChange={(e) =>
                          updateItem(
                            index,
                            'subtotal',
                            parseFloat(e.target.value),
                          )
                        }
                      />
                    </div>
                    <div className="sm:col-span-2 relative">
                      <Label className="text-xs font-semibold text-[#57715B] mb-1.5 block">
                        Categoria
                      </Label>
                      <div className="flex gap-1">
                        <Select
                          value={normalizeCategoria(item.categoria)}
                          onValueChange={(v) => updateItem(index, 'categoria', v)}
                        >
                          <SelectTrigger data-mia-filter={`itens[${index}].categoria`} className="rounded-lg border-[#57715B]/10 focus:border-[#57715B] h-9 text-sm">
                            <SelectValue placeholder="Categoria" />
                          </SelectTrigger>
                          <SelectContent>
                            {CATEGORIAS_NF.map((c) => (
                              <SelectItem key={c} value={c}>{c}</SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        <Button
                          variant="ghost"
                          size="icon"
                          data-mia-action="remover-item-nf"
                          data-mia-row-index={index}
                          className="h-9 w-9 text-[#57715B]/40 hover:text-red-500 hover:bg-red-50 shrink-0 hidden sm:flex rounded-full transition-colors"
                          onClick={() => removeItem(index)}
                          title="Remover item"
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  </div>
                </div>
              ))}

              {(!data.itens || data.itens.length === 0) && (
                <div className="text-center py-8 text-[#57715B]/40 border-2 border-dashed border-[#57715B]/10 rounded-2xl bg-[#57715B]/5">
                  Nenhum item adicionado ainda.
                </div>
              )}
            </div>

            {/* Botão de adicionar item também no final da lista se ela for longa */}
            {data.itens && data.itens.length > 3 && (
              <Button
                data-mia-action="adicionar-item-nf"
                data-mia-skip="true"
                aria-label="adicionar-outro-item-nf"
                variant="outline"
                size="sm"
                onClick={addItem}
                className="w-full mt-4 rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 hover:text-[#57715B]"
              >
                Adicionar Outro Item
              </Button>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="border-t border-[#57715B]/10 bg-[#F5F5F0] p-4 z-10 flex gap-3 justify-end rounded-b-xl">
          <Button
            variant="outline"
            data-mia-action="cancelar-nota-manual"
            data-mia-expects-toast="remov"
            onClick={onClose}
            disabled={isSaving}
            className="rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 hover:text-[#57715B]"
          >
            Cancelar
          </Button>
          <Button
            data-mia-action="salvar-nota-manual"
            data-mia-description="Salvar a nota fiscal manual (requer fornecedor preenchido)"
            data-mia-expects-modal-close="nova-nota-manual"
            data-mia-expects-toast="salv"
            onClick={handleSave}
            disabled={isSaving}
            className="rounded-full bg-[#57715B] hover:bg-[#4A614D] text-white font-bold shadow-lg shadow-[#57715B]/20 min-w-[140px]"
          >
            {isSaving ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Salvando...
              </>
            ) : (
              'Salvar Nota'
            )}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

